<title>Todo App</title>
<style>
*{box-sizing:border-box}
body{margin:0;min-height:100vh;background:linear-gradient(135deg,#667eea,#764ba2);font-family:system-ui,sans-serif;display:flex;justify-content:center;padding:40px 16px}
.app{background:#fff;width:100%;max-width:480px;border-radius:14px;box-shadow:0 10px 30px rgba(0,0,0,.25);padding:24px;align-self:flex-start}
h1{margin:0 0 16px;text-align:center;color:#333}
form{display:flex;gap:8px}
input[type=text]{flex:1;padding:10px 12px;border:2px solid #ddd;border-radius:8px;font-size:16px}
