.filters{display:flex;justify-content:center;gap:6px;margin:16px 0}
.filters button{border:1px solid #ddd;background:#fff;border-radius:16px;padding:5px 14px}
.filters button.active{background:#667eea;color:#fff;border-color:#667eea}
ul{list-style:none;margin:0;padding:0}
li{display:flex;align-items:center;gap:10px;padding:10px 4px;border-bottom:1px solid #eee}
