li input{width:18px;height:18px;cursor:pointer}
.del{border:0;background:none;color:#e55;font-size:20px;line-height:1}
.del:hover{color:#b00}
.footer{display:flex;justify-content:space-between;margin-top:12px;font-size:13px;color:#777}
.footer button{border:0;background:none;color:#777;text-decoration:underline}
.empty{text-align:center;color:#aaa;padding:20px 0}
</style>
</head>
<body>
<div class="app">
  <h1>Todo List</h1>
  <form id="form">
    <input type="text" id="input" placeholder="What needs to be done?" autocomplete="off" autofocus>
    <button class="add" type="submit">Add</button>
  </form>
  <div class="filters" id="filters">
    <button data-f="all" class="active">All</button>
    <button data-f="active">Active</button>
    <button data-f="completed">Completed</button>
  </div>
  <ul id="list"></ul>
  <div class="footer">
    <span id="count"></span>
    <button id="clear">Clear completed</button>
  </div>
</div>
<script>
const KEY = 'todos-v1';
let todos = [];
try { todos = JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { todos = []; }
let filter = 'all';

const $ = id => document.getElementById(id);
const save = () => { try { localStorage.setItem(KEY, JSON.stringify(todos)); } catch (e) {} };

function render() {
  const list = $('list');
  list.innerHTML = '';
  const shown = todos.filter(t => filter === 'all' || (filter === 'active' ? !t.done : t.done));
  if (!shown.length) {
    const p = document.createElement('div');
    p.className = 'empty';
    p.textContent = 'Nothing here.';
    list.appendChild(p);
  }
  shown.forEach(t => {
    const li = document.createElement('li');
    if (t.done) li.className = 'done';
    const cb = document.createElement('input');
    cb.type = 'checkbox';
    cb.checked = t.done;
    cb.onchange = () => { t.done = cb.checked; save(); render(); };
    const sp = document.createElement('span');
    sp.textContent = t.text;
    const del = document.createElement('button');
    del.className = 'del';
    del.innerHTML = '&times;';
    del.title = 'Delete';
    del.onclick = () => { todos = todos.filter(x => x.id !== t.id); save(); render(); };
    li.append(cb, sp, del);
    list.appendChild(li);
  });
  const left = todos.filter(t => !t.done).length;
  $('count').textContent = left + (left === 1 ? ' item' : ' items') + ' left';
  $('clear').style.visibility = todos.some(t => t.done) ? 'visible' : 'hidden';
  document.querySelectorAll('#filters button').forEach(b =>
    b.classList.toggle('active', b.dataset.f === filter));
}

$('form').onsubmit = e => {
  e.preventDefault();
  const text = $('input').value.trim();
  if (!text) return;
  todos.push({ id: Date.now() + Math.random(), text, done: false });
  $('input').value = '';
  save(); render();
};
$('filters').onclick = e => {
  if (e.target.dataset.f) { filter = e.target.dataset.f; render(); }
};
$('clear').onclick = () => { todos = todos.filter(t => !t.done); save(); render(); };
render();
</script>
</body>
</html>
